import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import "./gamestyles.css";
import ParticlesBackground from './ParticlesBackground';

export default function LocalGame() {
  const [board, setBoard] = useState(Array(9).fill(null));
  const [xTurn, setXTurn] = useState(true);
  const [winner, setWinner] = useState(null);
  const [winningLine, setWinningLine] = useState(null);
  const navigate = useNavigate();

  // Sound refs
  const loseSound = useRef(new Audio(`${process.env.PUBLIC_URL}/sounds/lose.mp3`));
const winSound = useRef(new Audio(`${process.env.PUBLIC_URL}/sounds/win.mp3`));
const drawSound = useRef(new Audio(`${process.env.PUBLIC_URL}/sounds/draw.mp3`));


  useEffect(() => {
    if (!winner) return;

    if (winner === "Draw") {
      drawSound.current.currentTime = 0;
      drawSound.current.play();
    } else if (winner === "X") {
      winSound.current.currentTime = 0;
      winSound.current.play();
    } else if (winner === "O") {
      loseSound.current.currentTime = 0;
      loseSound.current.play();
    }
  }, [winner]);

  const checkWinner = (b) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // cols
      [0, 4, 8], [2, 4, 6],           // diagonals
    ];
    for (let [a, b1, c] of lines) {
      if (b[a] && b[a] === b[b1] && b[a] === b[c]) {
        setWinningLine([a, b1, c]);
        return b[a];
      }
    }
    return b.every(cell => cell) ? "Draw" : null;
  };

  const handleClick = (index) => {
    if (board[index] || winner) return;

    const newBoard = [...board];
    newBoard[index] = xTurn ? "X" : "O";
    setBoard(newBoard);

    const result = checkWinner(newBoard);
    if (result) setWinner(result);
    else setXTurn(!xTurn);
  };

  const resetGame = () => {
    setBoard(Array(9).fill(null));
    setWinner(null);
    setXTurn(true);
    setWinningLine(null);
  };

  return (
  <div style={{ position: "relative", minHeight: "100vh", overflow: "hidden" }}>
    <ParticlesBackground />
    
    <div
      style={{
        position: "relative",
        zIndex: 2,
        textAlign: "center",
        paddingTop: "50px",
        color: "#f0f0f0",
      }}
    >
      <div className="app">
        <h2 className="game-heading">2 Player Offline</h2>

        <div className="grid">
          {board.map((val, idx) => {
            const isWinningCell = winningLine?.includes(idx);
            return (
              <div
                key={idx}
                onClick={() => handleClick(idx)}
                className={`cell ${val ? "filled" : ""} ${winner ? "disabled" : ""} ${
                  isWinningCell ? "win-cell" : ""
                }`}
              >
                {val}
              </div>
            );
          })}
        </div>

        <h3 className="status-text">
          {winner
            ? winner === "Draw"
              ? "It's a draw!"
              : `Player ${winner} wins!`
            : `Turn: ${xTurn ? "X" : "O"}`}
        </h3>

        <div className="btn-group">
          <button className="btn" onClick={resetGame}>
            Restart
          </button>
          <button className="btn" onClick={() => navigate("/")}>
            Back to Home
          </button>
        </div>
      </div>
    </div>
  </div>
);
}