import { getFirestore, doc, setDoc, updateDoc, onSnapshot, getDoc, deleteDoc } from "firebase/firestore";
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import "./gamestyles.css";
import ParticlesBackground from './ParticlesBackground';

const db = getFirestore();

function OnlineGame() {
  const [roomCode, setRoomCode] = useState('');
  const [inputRoomCode, setInputRoomCode] = useState('');
  const [isRoomCreated, setIsRoomCreated] = useState(false);
  const [isGameStarted, setIsGameStarted] = useState(false);
  const [board, setBoard] = useState(Array(9).fill(null));
  const [myTurn, setMyTurn] = useState(false);
  const [playerSymbol, setPlayerSymbol] = useState(null);
  const [opponentLeft, setOpponentLeft] = useState(false);
  const [turn, setTurn] = useState('X');
  const [timer, setTimer] = useState(10);
  const [winner, setWinner] = useState(null);
  const [winningLine, setWinningLine] = useState(null);
  

  const timerRef = useRef(null);
  const unsubscribeRef = useRef(null);
  const playerId = useRef(Math.random().toString(36).substr(2, 9));
  const winSound = useRef(new Audio("/sounds/win.mp3"));
  const loseSound = useRef(new Audio("/sounds/lose.mp3"));
  const drawSound = useRef(new Audio("/sounds/draw.mp3"));
  const navigate = useNavigate();
  const [showMultiplayerOptions, setShowMultiplayerOptions] = useState(false);
const [startGame, setStartGame] = useState(false);

  const checkWinner = (b) => {
    const lines = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8],
      [0, 3, 6], [1, 4, 7], [2, 5, 8],
      [0, 4, 8], [2, 4, 6],
    ];
    for (let [a, b1, c] of lines) {
      if (b[a] && b[a] === b[b1] && b[a] === b[c]) {
        setWinningLine([a, b1, c]);
        return b[a];
      }
    }
    return b.every(cell => cell !== null) ? "Draw" : null;
  };

  const resetGame = async () => {
    if (!roomCode) return;
    const roomRef = doc(db, "rooms", roomCode);
    await updateDoc(roomRef, {
      board: Array(9).fill(null),
      turn: 'X',
    });
    setWinner(null);
    setWinningLine(null);
  };

  const handleCreateRoom = async () => {
    if (isRoomCreated) return;
    const code = Math.random().toString(36).substr(2, 6).toUpperCase();
    const roomRef = doc(db, "rooms", code);

    await setDoc(roomRef, {
      board: Array(9).fill(null),
      turn: 'X',
      players: [{ id: playerId.current, symbol: 'X' }],
    });

    setRoomCode(code);
    setIsRoomCreated(true);
    setPlayerSymbol('X');
    setMyTurn(true);
    setIsGameStarted(true);
  };

  const handleJoinRoom = async () => {
    const roomRef = doc(db, "rooms", inputRoomCode.trim().toUpperCase());
    const snapshot = await getDoc(roomRef);

    if (!snapshot.exists()) return alert("Room not found.");
    const data = snapshot.data();
    if (data.players.length >= 2) return alert("Room is full.");

    await updateDoc(roomRef, {
      players: [...data.players, { id: playerId.current, symbol: 'O' }]
    });

    setRoomCode(inputRoomCode);
    setPlayerSymbol('O');
    setMyTurn(false);
    setIsGameStarted(true);
  };

  const handleClick = async (index) => {
    if (!myTurn || board[index] || !roomCode || winner) return;

    const updatedBoard = [...board];
    updatedBoard[index] = playerSymbol;

    const roomRef = doc(db, "rooms", roomCode);
    await updateDoc(roomRef, {
      board: updatedBoard,
      turn: playerSymbol === 'X' ? 'O' : 'X',
    });

    setMyTurn(false);
  };

  const handleSkipTurn = async () => {
    const roomRef = doc(db, "rooms", roomCode);
    await updateDoc(roomRef, {
      turn: playerSymbol === 'X' ? 'O' : 'X'
    });
    setMyTurn(false);
  };

  useEffect(() => {
    if (!roomCode) return;

    const roomRef = doc(db, "rooms", roomCode);
    const unsubscribe = onSnapshot(roomRef, async (snapshot) => {
      if (!snapshot.exists()) {
        alert("Room deleted");
        setRoomCode('');
        setIsGameStarted(false);
        return;
      }

      const data = snapshot.data();
      setBoard(data.board || Array(9).fill(null));
      setTurn(data.turn);

      const currentPlayer = data.players.find(p => p.id === playerId.current);
      const opponent = data.players.find(p => p.id !== playerId.current);

      setOpponentLeft(!opponent);
      setMyTurn(data.turn === playerSymbol);

      const gameWinner = checkWinner(data.board);
      setWinner(gameWinner);
    });

    unsubscribeRef.current = unsubscribe;

    return () => unsubscribe();
  }, [roomCode, playerSymbol]);

  useEffect(() => {
    if (!myTurn || opponentLeft || winner) return;

    setTimer(10);
    clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer(prev => {
        if (prev === 1) {
          clearInterval(timerRef.current);
          handleSkipTurn();
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timerRef.current);
  }, [myTurn, winner]);

  useEffect(() => {
    if (!winner) return;
    if (winner === "Draw") drawSound.current.play();
    else if (winner === playerSymbol) winSound.current.play();
    else loseSound.current.play();
  }, [winner]);

  useEffect(() => {
    const handleBeforeUnload = async () => {
      if (!roomCode) return;
      const roomRef = doc(db, "rooms", roomCode);
      const snapshot = await getDoc(roomRef);
      if (!snapshot.exists()) return;

      const data = snapshot.data();
      const updatedPlayers = data.players.filter(p => p.id !== playerId.current);

      if (updatedPlayers.length === 0) {
        await deleteDoc(roomRef);
      } else {
        await updateDoc(roomRef, { players: updatedPlayers });
      }
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      handleBeforeUnload(); // On component unmount
    };
  }, [roomCode]);

  return (
    <div style={{ position: "relative", minHeight: "100vh", overflow: "hidden" }}>
      <ParticlesBackground />
      <div style={{ position: "relative", zIndex: 2, textAlign: "center", paddingTop: "50px", color: "#f0f0f0" }}>
        <div className="app">
          <h1>Multiplayer Tic Tac Toe</h1>

          {!isGameStarted && (
            <div className="multiplayer-options">
              <input
                type="text"
                placeholder="Enter Room Code"
                className="room-input"
                value={inputRoomCode}
                onChange={(e) => setInputRoomCode(e.target.value)}
              />
              <button onClick={handleJoinRoom}>Join</button>

              <button
                onClick={handleCreateRoom}
                disabled={isRoomCreated}
                style={{ marginTop: "12px" }}
              >
                {isRoomCreated ? "Waiting for Opponent..." : "Create Room"}
              </button>
            </div>
          )}

          {roomCode && (
            <div className="room-code">
              Room Code: <strong>{roomCode}</strong>
            </div>
          )}
                 <button
  className="btn"
  onClick={() => {
    navigate("/");
    setShowMultiplayerOptions(false);
    setStartGame(false);
  }}
>
  Back to Home
</button>

          {isGameStarted && (
            <>
              <div className="status-bar">
                {opponentLeft && <div className="opponent-left">Opponent not available.</div>}
                <div className="turn-indicator">
                  Turn: {turn}
                  {myTurn && !opponentLeft && !winner && (
                    <span className="your-turn"> (Your Turn)</span>
                  )}
                </div>
                {myTurn && !opponentLeft && !winner && (
                  <div className="timer">⏳ {timer}s</div>
                )}
              </div>

              <div className="board">
                {board.map((cell, idx) => {
                  const isWinningCell = winningLine?.includes(idx);
                  return (
                    <div
                      key={idx}
                      className={`cell ${cell ? "filled" : ""} ${winner ? "disabled" : ""} ${
                        isWinningCell ? "win-cell" : ""
                      }`}
                      onClick={() => handleClick(idx)}
                    >
                      {cell}
                    </div>
                  );
                })}
              </div>

              <h3 className="status-text">
                {winner
                  ? winner === "Draw"
                    ? "It's a draw!"
                    : `Player ${winner} wins!`
                  : myTurn
                  ? "Your turn"
                  : "Waiting for opponent..."}
              </h3>

              <div className="btn-group">
                <button className="btn" onClick={resetGame}>Restart</button>
  
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default OnlineGame;
