import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { auth, db } from "../firebase";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  sendEmailVerification,
  sendPasswordResetEmail,
  signOut,
  onAuthStateChanged,
} from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import "./styles.css";

export default function AuthPage() {
  const navigate = useNavigate();

  const [view, setView] = useState("login");
  const [currentUser, setCurrentUser] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    username: "",
    email: "",
    password: "",
    forgotEmail: "",
  });

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
    });
    return () => unsubscribe();
  }, []);

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSignup = async () => {
    const { name, username, email, password } = formData;
    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        email.trim(),
        password
      );
      const user = userCredential.user;
      await sendEmailVerification(user);
      await setDoc(doc(db, "users", user.uid), { name, username, email });
      alert("Verify your email before logging in.");
      setView("login");
    } catch (err) {
      alert("Signup error: " + err.message);
    }
  };

  const handleLogin = async () => {
    const { email, password } = formData;
    try {
      const userCredential = await signInWithEmailAndPassword(
        auth,
        email.trim(),
        password
      );
      const user = userCredential.user;
      if (user.emailVerified) {
        navigate("/"); // go to homepage
      } else {
        alert("Please verify your email.");
      }
    } catch (err) {
      alert("Login error: " + err.message);
    }
  };

  const handleForgotPassword = async () => {
  console.log("Forgot email:", formData.forgotEmail); // debug
  if (!formData.forgotEmail || !formData.forgotEmail.trim()) {
    alert("Please enter your email.");
    return;
  }

  try {
    await sendPasswordResetEmail(auth, formData.forgotEmail.trim());
    alert("Reset email sent.(Check spam)");
    setView("login");
  } catch (err) {
    console.error("Reset error:", err); // debug
    alert("Reset error: " + err.message);
  }
};


  const handleSignOut = async () => {
    try {
      await signOut(auth);
      alert("Signed out successfully.");
      setView("login");
    } catch (err) {
      alert("Sign out error: " + err.message);
    }
  };

return (
  <div className="container">
    {currentUser && (
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <p>Signed in as {currentUser.email}</p>
        <button onClick={handleSignOut}>Sign Out</button>
      </div>
    )}

    {view === "login" && !currentUser && (
      <div className="login form">
        <header>Login</header>
        <input
          name="email"
          type="text"
          placeholder="Enter your email"
          onChange={handleChange}
        />
        <input
          name="password"
          type="password"
          placeholder="Enter your password"
          onChange={handleChange}
        />
        <div className="signup">
          <a onClick={() => setView("forgot")}>Forgot password?</a>
        </div>
        <input
          type="button"
          className="button loginbtn"
          value="Login"
          onClick={handleLogin}
        />
        <div className="signup">
          <span>Don't have an account? </span>
          <a onClick={() => setView("signup")}>Signup</a>
        </div>
        <div className="redirect">
          <div className="redirect-text">
            <a onClick={() => navigate("/")}>Continue Playing</a>
          </div>
        </div>
      </div>
    )}

    {view === "signup" && !currentUser && (
      <div className="login form">
        <header>Signup</header>
        <input
          name="name"
          type="text"
          placeholder="Enter your name"
          onChange={handleChange}
        />
        <input
          name="username"
          type="text"
          placeholder="Enter your username"
          onChange={handleChange}
        />
        <input
          name="email"
          type="text"
          placeholder="Enter your email"
          onChange={handleChange}
        />
        <input
          name="password"
          type="password"
          placeholder="Create a password"
          onChange={handleChange}
        />
        <input
          type="button"
          className="button signupbtn"
          value="Signup"
          onClick={handleSignup}
        />
        <div className="signup">
          <span>Already have an account? </span>
          <a onClick={() => setView("login")}>Login</a>
        </div>
        <div className="redirect">
          <div className="redirect-text">
            <a onClick={() => navigate("/")}>Continue Playing</a>
          </div>
        </div>
      </div>
    )}

    {view === "forgot" && !currentUser && (
      <div className="login form">
        <header>Forgot Password</header>
        <input
          name="forgotEmail"
          type="text"
          placeholder="Enter your email"
          onChange={handleChange}
        />
        <input
          type="button"
          className="button forgotbtn"
          value="Submit"
          onClick={handleForgotPassword}
        />
        <div className="signup">
          <span>Don't have an account? </span>
          <a onClick={() => setView("signup")}>Signup</a>
        </div>
        <div className="signup">
          <span>Already have an account? </span>
          <a onClick={() => setView("login")}>Login</a>
        </div>
        <div className="redirect">
          <div className="redirect-text">
            <a onClick={() => navigate("/")}>Continue Playing</a>
          </div>
        </div>
      </div>
    )}
  </div>
);
}
